#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    long long maximizeSumOfSquares(vector<int>& digits, int k) {
        priority_queue<pair<int, int>> pq; // {gain, index}
        vector<int> d_vals = digits;
        for (int i = 0; i < (int)d_vals.size(); ++i) {
            if (d_vals[i] < 9) {
                pq.push({2 * d_vals[i] + 1, i});
            }
        }
        while (k > 0 && !pq.empty()) {
            auto [gain, idx] = pq.top();
            pq.pop();
            d_vals[idx]++;
            k--;
            if (d_vals[idx] < 9) {
                pq.push({2 * d_vals[idx] + 1, idx});
            }
        }
        long long total = 0;
        for (int x : d_vals) total += 1LL * x * x;
        return total;
    }
};

import java.util.*;

class Solution {
    public long maximizeSumOfSquares(int[] digits, int k) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]); // [gain, idx]
        int[] dVals = digits.clone();
        for (int i = 0; i < dVals.length; i++) {
            if (dVals[i] < 9) {
                pq.offer(new int[]{2 * dVals[i] + 1, i});
            }
        }
        while (k > 0 && !pq.isEmpty()) {
            int[] top = pq.poll();
            int idx = top[1];
            dVals[idx]++;
            k--;
            if (dVals[idx] < 9) {
                pq.offer(new int[]{2 * dVals[idx] + 1, idx});
            }
        }
        long total = 0;
        for (int x : dVals) total += (long)x * x;
        return total;
    }
}

var maximizeSumOfSquares = function(digits, k) {
    const dVals = [...digits];
    for (let step = 0; step < k; step++) {
        let bestGain = -1;
        let bestIdx = -1;
        for (let i = 0; i < dVals.length; i++) {
            if (dVals[i] < 9) {
                const gain = 2 * dVals[i] + 1;
                if (gain > bestGain) {
                    bestGain = gain;
                    bestIdx = i;
                }
            }
        }
        if (bestIdx === -1) break;
        dVals[bestIdx]++;
    }
    return dVals.reduce((sum, x) => sum + x * x, 0);
};
